/* Flicsy — Phase 1. Visual language carried over from the Mira Picks publication and agent console. */
:root {
  --ink: #111; --paper: #f5f2ed; --card: #fbfaf7; --muted: #6f6a63; --line: #d9d3ca;
  --accent: #b5543a; --pink: #c2185b; --blue: #2f4f9e;
  --working: #c08a2d; --working-bg: #fbf3e4; --done: #2d7a46; --blocked: #b3261e;
  --serif: 'Cormorant Garamond', Georgia, serif; --sans: 'Inter', system-ui, sans-serif;
  --mono: 'JetBrains Mono', ui-monospace, Consolas, monospace;
  --gutter: clamp(20px, 4vw, 56px); --max: 1320px;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html { background: var(--paper); scroll-behavior: smooth; }
body { font-family: var(--sans); color: var(--ink); background: var(--paper); -webkit-font-smoothing: antialiased; overflow-x: hidden; }
a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; height: 100%; object-fit: cover; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
[hidden] { display: none !important; }
em { font-style: italic; }

/* ---------- Shared editorial pieces ---------- */
.topbar { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 12px var(--gutter);
  font-size: 11px; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); border-bottom: 1px solid var(--line); }
.topbar a:hover { color: var(--accent); }
.masthead { text-align: center; padding: clamp(28px, 5vw, 64px) var(--gutter) clamp(16px, 2.5vw, 28px); }
.masthead a { font-family: var(--serif); font-weight: 500; font-size: clamp(56px, 13vw, 196px); line-height: .85;
  letter-spacing: -.02em; text-transform: uppercase; display: inline-block; }
.tagline { margin-top: 14px; font-family: var(--serif); font-style: italic; font-size: clamp(16px, 1.6vw, 21px); color: var(--muted); }
.site-nav { position: sticky; top: 0; z-index: 50; background: rgba(245, 242, 237, .92); backdrop-filter: blur(8px);
  border-top: 1px solid var(--ink); border-bottom: 1px solid var(--line); }
.site-nav ul { list-style: none; display: flex; justify-content: center; gap: clamp(18px, 4vw, 56px); padding: 14px var(--gutter);
  font-size: 12px; letter-spacing: .18em; text-transform: uppercase; flex-wrap: wrap; }
.site-nav a { padding-bottom: 3px; border-bottom: 1px solid transparent; transition: color .2s, border-color .2s; }
.site-nav a:hover, .site-nav a.on { color: var(--accent); }
.site-nav a.on { border-color: var(--accent); }
.kicker { display: flex; align-items: center; gap: 10px; font-size: 11px; letter-spacing: .2em; text-transform: uppercase; color: var(--accent); font-weight: 600; }
.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--accent); flex: none; }
.deck { font-family: var(--serif); font-size: clamp(20px, 1.8vw, 26px); line-height: 1.35; color: #2a2723; max-width: 40ch; }
.label { font-size: 11px; letter-spacing: .2em; text-transform: uppercase; color: var(--muted); font-weight: 500; }
.fine { font-size: 12px; color: var(--muted); line-height: 1.5; margin-top: 12px; }
.cta { display: inline-flex; align-items: center; gap: 12px; font-size: 12px; letter-spacing: .2em; text-transform: uppercase; font-weight: 600;
  padding: 18px 28px; background: var(--ink); color: var(--paper); transition: background .3s, opacity .3s; }
.cta:hover { background: var(--accent); }
.cta:disabled { opacity: .35; cursor: not-allowed; background: var(--ink); }
.cta-block { width: 100%; justify-content: center; margin-top: 24px; }
.btn-ink { font-size: 11px; letter-spacing: .18em; text-transform: uppercase; font-weight: 600; padding: 0 22px; background: var(--ink); color: var(--paper); }
.btn-ink:hover { background: var(--accent); }
.btn-line { font-size: 11px; letter-spacing: .18em; text-transform: uppercase; font-weight: 600; padding: 12px 18px; border: 1px solid var(--ink); background: transparent; }
.btn-line:hover { background: var(--ink); color: var(--paper); }
.link { font-size: inherit; color: var(--accent); border-bottom: 1px solid currentColor; padding: 0; }

/* ---------- 1. Intro (Mira Picks front page) ---------- */
.lead { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); min-height: 86vh; border-bottom: 1px solid var(--line); }
.lead-img { overflow: hidden; background: #e8e3dc; }
.lead-img img { object-position: center 20%; animation: slowzoom 18s ease-out both; }
@keyframes slowzoom { from { transform: scale(1.06); } to { transform: scale(1); } }
.lead-copy { display: flex; flex-direction: column; justify-content: flex-end; padding: clamp(32px, 5vw, 80px); }
.lead h1 { font-family: var(--serif); font-weight: 500; font-size: clamp(48px, 6vw, 100px); line-height: .95; letter-spacing: -.015em; margin: 22px 0 26px; }
.lead h1 em { color: var(--blue); }
.byline { margin-top: 32px; padding-top: 18px; border-top: 1px solid var(--line); font-size: 12px; letter-spacing: .14em; text-transform: uppercase; }
.byline span { color: var(--muted); letter-spacing: .04em; text-transform: none; font-size: 13px; line-height: 2; }
.lead .cta { margin-top: 34px; align-self: flex-start; }
.verdict { padding: clamp(64px, 9vw, 140px) var(--gutter); text-align: center; border-bottom: 1px solid var(--line); }
.verdict-label { font-size: 11px; letter-spacing: .24em; text-transform: uppercase; color: var(--muted); }
.verdict blockquote { font-family: var(--serif); font-style: italic; font-size: clamp(30px, 4.2vw, 64px); line-height: 1.08; max-width: 22ch; margin: 22px auto 0; }
.strip { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(8px, 1.2vw, 18px); margin-top: clamp(48px, 6vw, 88px); }
.strip-img { position: relative; aspect-ratio: 4 / 5; overflow: hidden; background: #e8e3dc; }
.strip-img img { transition: transform .8s ease; }
.strip-img:hover img { transform: scale(1.04); }
.strip-cap { position: absolute; left: 0; right: 0; bottom: 0; padding: 40px 18px 16px; text-align: left; font-family: var(--serif);
  font-size: clamp(17px, 1.5vw, 22px); line-height: 1.15; color: #fff; background: linear-gradient(transparent, rgba(0, 0, 0, .55)); }
.mp-desk { display: grid; grid-template-columns: minmax(0, 4fr) minmax(0, 8fr); gap: clamp(32px, 5vw, 80px); background: var(--ink); color: #f5f2ed;
  padding: clamp(64px, 8vw, 120px) var(--gutter); }
.mp-desk h2 { font-family: var(--serif); font-weight: 500; font-size: clamp(40px, 5vw, 76px); line-height: .95; }
.mp-desk h2 em { color: #8fb3ff; }
.mp-team { display: inline-block; margin-top: 24px; font-size: 12px; letter-spacing: .18em; text-transform: uppercase; border-bottom: 1px solid rgba(245, 242, 237, .5); padding-bottom: 3px; }
.mp-team:hover { color: #8fb3ff; border-color: #8fb3ff; }
.mp-roles { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 22px; }
.mp-role { border-top: 1px solid rgba(245, 242, 237, .3); padding-top: 18px; }
.mp-role img { width: 64px; height: 64px; border-radius: 10px; margin-bottom: 14px; filter: grayscale(.15); }
.mp-role b { display: block; font-family: var(--serif); font-size: 28px; font-weight: 500; margin-bottom: 4px; }
.mp-role small { display: block; font-size: 10px; letter-spacing: .18em; text-transform: uppercase; color: #a9a39a; margin-bottom: 12px; }
.mp-role p { font-size: 13px; line-height: 1.6; color: #d8d2c8; }
.mp-role .new { display: inline-block; margin-left: 6px; font-family: var(--sans); font-size: 9px; letter-spacing: .16em; color: var(--ink); background: #8fb3ff; padding: 2px 6px; vertical-align: middle; }
.mp-foot { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 28px var(--gutter); font-size: 11px;
  letter-spacing: .16em; text-transform: uppercase; color: var(--muted); border-top: 1px solid var(--line); }

/* ---------- App shell ---------- */
.app-mast { text-align: center; padding: clamp(22px, 3vw, 40px) var(--gutter) clamp(12px, 1.6vw, 20px); }
.wordmark { font-family: var(--serif); font-weight: 500; font-size: clamp(56px, 7vw, 104px); line-height: .85; letter-spacing: -.01em; text-transform: uppercase; }
.app-mast .tagline { margin-top: 8px; }
.bag-btn { font-size: 11px; letter-spacing: .14em; text-transform: uppercase; color: var(--ink); display: inline-flex; gap: 8px; align-items: center; }
.bag-btn span { min-width: 20px; height: 20px; border-radius: 10px; background: var(--ink); color: var(--paper); display: inline-grid; place-items: center; font-size: 10px; padding: 0 6px; }
.bag-btn.bump span { animation: bump .5s ease; }
@keyframes bump { 50% { transform: scale(1.35); background: var(--accent); } }
.app > .view { max-width: var(--max); margin: 0 auto; padding: clamp(32px, 4vw, 56px) var(--gutter) clamp(64px, 7vw, 100px); animation: rise .5s ease both; }
.app > .curtain-view { max-width: none; padding-left: 0; padding-right: 0; padding-top: 0; }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }

/* ---------- 2. Your Stylist ---------- */
.stylist { display: grid; grid-template-columns: minmax(0, 8fr) minmax(300px, 4fr); gap: clamp(24px, 3vw, 48px); align-items: start; }
.convo { background: var(--card); border: 1px solid var(--line); display: flex; flex-direction: column; min-height: 640px; }
.convo-head { display: flex; gap: 20px; align-items: center; padding: 24px 28px; border-bottom: 1px solid var(--line); }
.convo-head img { width: 84px; height: 84px; border-radius: 12px; }
.convo-head h2 { font-family: var(--serif); font-weight: 500; font-size: 40px; line-height: 1; margin: 6px 0 4px; }
.convo-head p { font-size: 13px; color: var(--muted); }
.thread { flex: 1; padding: 28px; display: flex; flex-direction: column; gap: 22px; max-height: 560px; overflow-y: auto; }
.msg { max-width: 78%; animation: rise .4s ease both; }
.msg.miranda { display: flex; gap: 14px; align-items: flex-start; }
.msg.miranda img { width: 36px; height: 36px; border-radius: 8px; flex: none; margin-top: 2px; }
.msg.miranda .bubble { font-family: var(--serif); font-size: 22px; line-height: 1.35; }
.msg.miranda .who { font-size: 10px; letter-spacing: .18em; text-transform: uppercase; color: var(--muted); margin-bottom: 4px; }
.msg.client { align-self: flex-end; background: var(--ink); color: var(--paper); padding: 14px 18px; font-size: 15px; line-height: 1.55; }
.msg.client .who { font-size: 10px; letter-spacing: .18em; text-transform: uppercase; color: #a9a39a; margin-bottom: 4px; }
.msg.client img { width: 120px; height: 150px; margin-top: 10px; }
.typing { display: inline-flex; gap: 5px; padding: 10px 0; }
.typing i { width: 6px; height: 6px; border-radius: 50%; background: var(--muted); animation: blink 1.2s infinite; }
.typing i:nth-child(2) { animation-delay: .2s; } .typing i:nth-child(3) { animation-delay: .4s; }
@keyframes blink { 0%, 80%, 100% { opacity: .2; } 40% { opacity: 1; } }
.composer { border-top: 1px solid var(--line); padding: 18px 28px 24px; }
.chips { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; }
.chips:empty { display: none; }
.chip { font-size: 13px; padding: 9px 16px; border: 1px solid var(--ink); background: transparent; transition: all .2s; }
.chip:hover, .chip.on { background: var(--ink); color: var(--paper); }
.chip.done { border-color: var(--accent); color: var(--accent); }
.chip.done:hover { background: var(--accent); color: #fff; }
.compose-row { display: flex; gap: 10px; }
.compose-row textarea { flex: 1; resize: none; font: 15px/1.5 var(--sans); padding: 12px 14px; border: 1px solid var(--line); background: #fff; color: var(--ink); }
.compose-row textarea:focus { outline: none; border-color: var(--ink); }
.brief { position: sticky; top: 72px; background: var(--card); border: 1px solid var(--line); padding: 26px; }
.brief-head { display: flex; justify-content: space-between; align-items: center; padding-bottom: 14px; border-bottom: 1px solid var(--ink); }
.brief-state { font-size: 10px; letter-spacing: .16em; text-transform: uppercase; padding: 4px 8px; background: var(--working-bg); color: var(--working); font-weight: 600; }
.brief-state.ready { background: #e7f2ea; color: var(--done); }
.brief dl { display: grid; grid-template-columns: 96px 1fr; }
.brief dt, .brief dd { padding: 11px 0; border-bottom: 1px solid var(--line); font-size: 13px; }
.brief dt { font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); padding-top: 13px; }
.brief dd { font-family: var(--serif); font-size: 18px; line-height: 1.25; }
.brief dd.empty { color: #b9b2a7; font-style: italic; }
.brief dd.fresh { animation: fresh 1.2s ease; }
@keyframes fresh { from { background: var(--working-bg); } to { background: transparent; } }
.photo { display: flex; gap: 14px; align-items: center; margin-top: 18px; padding: 14px; border: 1px dashed var(--line); cursor: pointer; transition: border-color .2s; }
.photo:hover { border-color: var(--ink); }
.photo-preview { width: 56px; height: 70px; flex: none; background: #ece7e0 center/cover; display: grid; place-items: center; color: var(--muted); font-size: 22px; }
.photo-preview:empty::before { content: "+"; }
.photo-copy { font-size: 12px; line-height: 1.5; color: var(--muted); }
.photo-copy strong { color: var(--ink); font-weight: 500; }

/* ---------- 3. The Fashion Desk ---------- */
.desk-tag { font-family: var(--serif); font-size: clamp(20px, 2vw, 26px); color: #3b3732; text-align: center; max-width: 60ch; margin: 0 auto; }
.run-bar { display: flex; justify-content: space-between; align-items: center; gap: 20px; margin: 28px 0 40px; padding: 16px 20px; background: var(--card); border: 1px solid var(--line); }
.run-brief { font-size: 14px; line-height: 1.5; color: #3b3732; }
.run-brief b { font-weight: 600; }
.run-actions { display: flex; gap: 10px; flex: none; }
.stages { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 14px; position: relative; }
.stage { display: flex; flex-direction: column; align-items: center; position: relative; }
.stage:not(:last-child)::after { content: "→"; position: absolute; right: -12px; top: 44px; color: #b9b2a7; font-size: 14px; }
.portrait { width: 96px; height: 96px; border-radius: 14px; overflow: hidden; margin-bottom: 12px; border: 3px solid transparent; transition: border-color .3s, transform .3s, filter .3s; filter: grayscale(.55) opacity(.75); }
.stage.working .portrait { border-color: var(--working); transform: translateY(-4px); filter: none; box-shadow: 0 10px 24px rgba(192, 138, 45, .28); }
.stage.done .portrait { border-color: var(--done); filter: none; }
.stage.blocked .portrait { border-color: var(--blocked); filter: none; }
.card { width: 100%; flex: 1; background: #fff; border: 1px solid var(--line); padding: 16px 14px 14px; display: flex; flex-direction: column; transition: border-color .3s, background .3s; }
.stage.working .card { border: 2px solid var(--working); background: var(--working-bg); padding: 15px 13px 13px; }
.stage.done .card { border: 2px solid var(--done); padding: 15px 13px 13px; }
.stage.blocked .card { border: 2px solid var(--blocked); background: #fbeceb; padding: 15px 13px 13px; }
.card h3 { font-family: var(--sans); font-size: 16px; font-weight: 600; line-height: 1.2; }
.card .role { font-size: 12px; color: var(--muted); margin-top: 3px; }
.card .q { font-family: var(--serif); font-style: italic; font-size: 16px; line-height: 1.25; margin-top: 10px; color: #2a2723; }
.card .status { margin-top: auto; padding-top: 12px; }
.pill { display: inline-block; font-size: 9px; letter-spacing: .16em; text-transform: uppercase; font-weight: 600; padding: 3px 7px; background: #efebe5; color: var(--muted); }
.working .pill { background: var(--working); color: #fff; }
.done .pill { background: var(--done); color: #fff; }
.blocked .pill { background: var(--blocked); color: #fff; }
.card .line { display: block; font-size: 12px; line-height: 1.4; margin-top: 7px; color: var(--muted); min-height: 2.8em; }
.working .line { color: #8a5a2d; }
.working .line::after { content: ""; display: inline-block; width: 1.2em; text-align: left; animation: dots 1.2s steps(4) infinite; }
@keyframes dots { 0% { content: ""; } 25% { content: "."; } 50% { content: ".."; } 75% { content: "..."; } }
.drawers { margin-top: 44px; display: grid; gap: 14px; }
.drawer { background: #fff; border: 1px solid var(--line); }
.drawer > summary { list-style: none; cursor: pointer; display: flex; align-items: center; gap: 16px; padding: 18px 22px; }
.drawer > summary::-webkit-details-marker { display: none; }
.drawer > summary::before { content: "▸"; font-size: 11px; color: var(--muted); transition: transform .2s; }
.drawer[open] > summary::before { transform: rotate(90deg); }
.drawer .d-title { font-size: 12px; letter-spacing: .2em; text-transform: uppercase; font-weight: 600; color: #4a4640; }
.drawer .d-meta { font-family: var(--serif); font-size: 18px; color: #3b3732; }
.drawer .d-state { margin-left: auto; font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); }
.drawer.ready .d-state { color: var(--done); font-weight: 600; }
.drawer.fresh { animation: fresh 1.6s ease; }
.drawer .d-body { padding: 4px 22px 26px; border-top: 1px solid var(--line); }
.drawer .d-note { font-size: 11px; letter-spacing: .08em; color: var(--muted); margin: 16px 0; font-style: italic; }
.locked { padding: 18px 0 4px; font-family: var(--serif); font-style: italic; font-size: 18px; color: #9b948a; }
.press-grid { display: grid; grid-template-columns: 3fr 2fr; gap: 32px; }
.src { display: grid; grid-template-columns: 150px 1fr auto; gap: 14px; padding: 12px 0; border-bottom: 1px solid var(--line); align-items: baseline; }
.src b { font-family: var(--serif); font-size: 20px; font-weight: 500; }
.src span { font-size: 14px; line-height: 1.4; }
.src small { font-size: 10px; letter-spacing: .14em; text-transform: uppercase; color: var(--done); font-weight: 600; }
.src.paywalled span, .src.paywalled small { color: var(--muted); }
.signal { padding: 12px 0; border-bottom: 1px solid var(--line); font-family: var(--serif); font-size: 19px; line-height: 1.3; }
.signal i { display: block; font-family: var(--sans); font-style: normal; font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--accent); margin-bottom: 3px; font-weight: 600; }
.clip-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; }
.clip { aspect-ratio: 9 / 13; color: #fff; padding: 16px; display: flex; flex-direction: column; justify-content: flex-end; position: relative; overflow: hidden; }
.clip::before { content: "▶"; position: absolute; top: 14px; right: 14px; font-size: 12px; opacity: .8; }
.clip p { font-size: 14px; line-height: 1.35; font-weight: 500; }
.clip small { font-size: 11px; opacity: .8; margin-top: 8px; }
.clip b { font-size: 11px; letter-spacing: .1em; margin-top: 6px; }
.tags { display: flex; gap: 8px; flex-wrap: wrap; margin: 4px 0 18px; }
.tag { font-size: 11px; letter-spacing: .1em; text-transform: uppercase; padding: 6px 10px; border: 1px solid var(--line); }
.bag-looks { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 22px; margin-top: 18px; }
.bag-look h4 { font-family: var(--serif); font-weight: 500; font-size: 24px; margin-bottom: 10px; display: flex; justify-content: space-between; align-items: baseline; }
.bag-look h4 span { font-family: var(--sans); font-size: 13px; font-weight: 600; }
.mini { display: grid; grid-template-columns: 52px 1fr auto; gap: 12px; align-items: center; padding: 8px 0; border-top: 1px solid var(--line); font-size: 13px; line-height: 1.35; }
.mini img { width: 52px; height: 64px; }
.mini small { display: block; color: var(--muted); font-size: 11px; }
.mini.struck { opacity: .45; text-decoration: line-through; }
.mini.swapped { background: #e7f2ea; animation: fresh 1.6s ease; }
.over { color: var(--blocked); }
.notes-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; margin-top: 8px; }
.check { display: grid; grid-template-columns: 110px 1fr 20px; gap: 10px; padding: 10px 0; border-bottom: 1px solid var(--line); font-size: 14px; }
.check b { font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); font-weight: 500; padding-top: 2px; }
.check .ok { color: var(--done); } .check .warn { color: var(--working); }
.nigel-q { font-family: var(--serif); font-size: 21px; line-height: 1.35; padding: 14px 0; border-bottom: 1px solid var(--line); }
.nigel-q i { display: block; font-family: var(--sans); font-style: normal; font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); margin-bottom: 4px; }
.nigel-q.reject i { color: var(--blocked); font-weight: 600; }
.verdict-card { margin-top: 28px; display: grid; grid-template-columns: auto 1fr auto; gap: 26px; align-items: center; background: var(--ink); color: var(--paper); padding: 28px 32px; animation: rise .5s ease both; }
.verdict-card img { width: 72px; height: 72px; border-radius: 12px; }
.verdict-card .label { color: #a9a39a; }
.verdict-card blockquote { font-family: var(--serif); font-style: italic; font-size: clamp(24px, 2.4vw, 34px); line-height: 1.15; margin-top: 6px; }
.verdict-card .cta { background: var(--paper); color: var(--ink); }
.verdict-card .cta:hover { background: #8fb3ff; }

/* ---------- 4. Behind the Curtain (deliberately un-editorial) ---------- */
.curtain-view { background: #0f1012; color: #d7d9de; }
.room { display: grid; grid-template-columns: 280px 1fr; min-height: 78vh; font-family: var(--sans); }
.room-side { border-right: 1px solid #23262c; padding: 28px 24px; background: #0b0c0e; }
.room-brand { font-family: var(--mono); font-size: 20px; color: #fff; }
.room-brand span { color: #6b7280; }
.room-name { font-family: var(--mono); font-size: 14px; color: #8fb3ff; margin-top: 18px; }
.room-meta { font-size: 12px; color: #6b7280; line-height: 1.5; margin-top: 6px; }
.room-sec { font-size: 10px; letter-spacing: .18em; text-transform: uppercase; color: #6b7280; margin: 26px 0 10px; }
.seats, .tools-list, .legend { list-style: none; display: grid; gap: 8px; font-size: 13px; }
.seat { display: flex; gap: 10px; align-items: center; }
.seat img { width: 28px; height: 28px; border-radius: 6px; }
.seat code { font-family: var(--mono); font-size: 12px; color: #fff; }
.seat small { display: block; font-size: 11px; color: #6b7280; }
.seat .st { margin-left: auto; width: 8px; height: 8px; border-radius: 50%; background: #374151; }
.seat .st.working { background: var(--working); box-shadow: 0 0 0 4px rgba(192, 138, 45, .2); }
.seat .st.done { background: #3fb36b; } .seat .st.blocked { background: #e5484d; }
.tools-list li { font-family: var(--mono); font-size: 12px; color: #9ca3af; }
.tools-list b { color: #e6c07b; font-weight: 500; }
.legend li { display: flex; gap: 10px; align-items: center; font-size: 12px; color: #9ca3af; }
.lg { width: 10px; height: 10px; display: inline-block; }
.lg.mention { background: #8fb3ff; } .lg.tool { background: #e6c07b; } .lg.reject { background: #e5484d; } .lg.approve { background: #3fb36b; }
.room-main { display: flex; flex-direction: column; min-width: 0; }
.room-top { display: flex; justify-content: space-between; padding: 14px 28px; border-bottom: 1px solid #23262c; font-size: 12px; color: #6b7280; }
.live { font-family: var(--mono); font-size: 11px; text-transform: uppercase; letter-spacing: .1em; }
.live.on { color: #3fb36b; } .live.on::before { content: "● "; animation: blink 1.4s infinite; }
.feed { list-style: none; padding: 20px 28px 60px; display: grid; gap: 4px; max-height: 76vh; overflow-y: auto; }
.feed-empty { color: #6b7280; font-size: 14px; padding: 40px 0; }
.feed-empty a { color: #8fb3ff; }
.ev { display: grid; grid-template-columns: 64px 36px 1fr; gap: 12px; padding: 10px 0; animation: rise .35s ease both; }
.ev time { font-family: var(--mono); font-size: 11px; color: #4b5563; padding-top: 3px; }
.ev img { width: 32px; height: 32px; border-radius: 6px; }
.ev .who { font-size: 13px; font-weight: 600; color: #fff; }
.ev .who code { font-family: var(--mono); font-weight: 400; color: #6b7280; margin-left: 6px; font-size: 12px; }
.ev .txt { font-size: 14px; line-height: 1.55; color: #d7d9de; margin-top: 2px; }
.ev .txt .m { color: #8fb3ff; background: rgba(143, 179, 255, .12); padding: 0 4px; border-radius: 3px; font-family: var(--mono); font-size: 13px; }
.ev .handoff { display: inline-block; margin-top: 6px; font-family: var(--mono); font-size: 11px; color: #8fb3ff; }
.ev.system { grid-template-columns: 64px 1fr; }
.ev.system .txt { font-family: var(--mono); font-size: 12px; color: #6b7280; border-top: 1px dashed #23262c; border-bottom: 1px dashed #23262c; padding: 6px 0; }
.toolcall { margin-top: 6px; font-family: var(--mono); font-size: 12px; background: #16181c; border: 1px solid #23262c; border-left: 3px solid #e6c07b; padding: 10px 12px; color: #c9ccd3; overflow-x: auto; white-space: nowrap; }
.toolcall b { color: #e6c07b; font-weight: 500; }
.toolcall .res { display: block; color: #3fb36b; margin-top: 4px; }
.ev.reject .txt { border-left: 3px solid #e5484d; background: rgba(229, 72, 77, .08); padding: 8px 12px; }
.ev.reject .tagx { font-family: var(--mono); font-size: 10px; color: #e5484d; letter-spacing: .1em; }
.ev.approve .txt { border-left: 3px solid #3fb36b; background: rgba(63, 179, 107, .08); padding: 8px 12px; }
.ev.approve .tagx { font-family: var(--mono); font-size: 10px; color: #3fb36b; letter-spacing: .1em; }

/* ---------- 5. Your Looks ---------- */
.looks-hero { text-align: center; padding: clamp(16px, 3vw, 40px) 0 clamp(40px, 5vw, 72px); border-bottom: 1px solid var(--line); }
.looks-hero .kicker { justify-content: center; }
.looks-hero h1 { font-family: var(--serif); font-weight: 500; font-size: clamp(44px, 5.6vw, 88px); line-height: .98; letter-spacing: -.015em; margin: 20px auto 22px; max-width: 16ch; }
.looks-hero .deck { margin: 0 auto; }
.look { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 6fr); gap: clamp(28px, 4vw, 64px); padding: clamp(48px, 6vw, 88px) 0; border-bottom: 1px solid var(--line); }
