.look-img .num { position: absolute; top: 18px; left: 20px; font-family: var(--serif); font-size: 64px; line-height: 1; color: rgba(17, 17, 17, .8); }
.look-img .alt { position: absolute; top: 24px; right: 20px; font-size: 10px; letter-spacing: .18em; text-transform: uppercase; background: var(--paper); padding: 6px 10px; font-weight: 600; }
